const tr=k=>window.I18N?.t(k)||k;
const $=s=>document.querySelector(s);async function refresh(){const s=await window.mcp.status();$('#agentState').textContent=s.running?tr('agentRunning'):tr('agentStopped');$('#agentDetail').textContent=s.detail;$('#dot').className=s.running?'on':''}async function init(){const i=await window.mcp.info();$('#platform').textContent=`${i.platform} · ${i.arch}`;$('#version').textContent=`v${i.version}`;await refresh();await refreshDiagnosticLogs()}init();$('#repairAgent').onclick=async()=>{const r=await window.mcp.installAgent();if(!r.ok)showInfo(tr('installFailed'),r.error||'Unknown error');else{showInfo(tr('agentReady'),tr('agentReadyBody'));setTimeout(refresh,500)}};['start','restart','stop'].forEach(a=>$('#'+a).onclick=async()=>{const b=$('#'+a),oldText=b.textContent;b.disabled=true;b.textContent=a==='restart'?'Restarting…':a==='stop'?'Stopping…':'Starting…';try{const r=await window.mcp.action(a);if(!r?.ok)showInfo('Agent action failed',r?.stderr||r?.error||`Could not ${a} the Device Agent.`);await new Promise(x=>setTimeout(x,700));await refresh()}finally{b.disabled=false;b.textContent=oldText}});$('#openWeb').onclick=()=>window.mcp.openWeb();let activeLogTab='agent';async function refreshDiagnosticLogs(){const b=$('#refreshLogs');if(b){b.disabled=true;b.textContent='Refreshing…'}try{$('#logs').textContent=await window.mcp.logs(activeLogTab);$('#logsRefreshed').textContent=`Last refreshed ${new Date().toLocaleTimeString()}`}finally{if(b){b.disabled=false;b.textContent=tr('refresh')}}}$('#refreshLogs').onclick=refreshDiagnosticLogs;document.querySelectorAll('[data-log-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-log-tab]').forEach(x=>x.classList.toggle('active',x===b));activeLogTab=b.dataset.logTab;refreshDiagnosticLogs()});document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active');$('#title').textContent=b.textContent;if(b.dataset.view==='diagnostics')refreshDiagnosticLogs();if(b.dataset.view==='mcps')renderConfig();if(b.dataset.view==='providers')renderProviders()})

const labels={get auto(){return tr('allow')},get confirm(){return tr('ask')},get deny(){return tr('off')}};
function permControl(name,current,onSet){const d=document.createElement('div');d.className='seg';['deny','confirm','auto'].forEach(p=>{const b=document.createElement('button');b.textContent=labels[p];b.className=(current===p?'active ':'')+p;b.onclick=async()=>{await onSet(p);await window.mcp.action('restart');await renderConfig();setTimeout(refresh,400)};d.appendChild(b)});return d}
async function renderConfig(){const [c,githubStatus,gdriveStatus]=await Promise.all([window.mcp.config(),window.mcp.githubToolStatus(),window.mcp.googleDriveToolStatus()]),cl=$('#capabilityList'),pl=$('#permissionList'),ml=$('#mcpList');const filesState=$('#filesToolState'),terminalState=$('#terminalToolState'),githubButton=$('#connectGithub'),gdriveButton=$('#connectGoogleDrive');if(githubButton){githubButton.textContent=githubStatus?.connected?'✓ Connected':(githubStatus?.installed?'Reconnect':'Connect');githubButton.classList.toggle('accent',!githubStatus?.connected)}if(gdriveButton){gdriveButton.textContent=gdriveStatus?.connected?`✓ Connected · ${gdriveStatus.selected||0} files`:(gdriveStatus?.configured?'Reconnect':'Connect');gdriveButton.classList.toggle('accent',!gdriveStatus?.connected)};if(filesState){const fp=(c.capabilities||{}).files||'confirm';filesState.textContent=fp==='deny'?'Off':'✓ Connected';filesState.classList.toggle('neutral',fp==='deny')}if(terminalState)renderTerminalState(terminalState);cl.innerHTML='';pl.innerHTML='';ml.innerHTML='';const caps={files:['Files & Folders','Read/write files and folders; Full Disk Access may be needed for protected locations.'],app_control:['App Control','Control or open other applications; may require Accessibility.'],screen:['Screen Recording','Capture or view the screen; requires Screen Recording permission.'],microphone:['Microphone','Access microphone input; requires Microphone permission.'],camera:['Camera','Access camera input; requires Camera permission.']};Object.entries(caps).forEach(([id,[title,desc]])=>{const row=document.createElement('div');row.className='permission-row capability-row';const info=document.createElement('div');const b=document.createElement('b');b.textContent=title;const sm=document.createElement('small');sm.textContent=desc;info.append(b,sm);row.append(info,permControl(id,(c.capabilities||{})[id]||'confirm',async p=>{if(p==='auto'){const osr=await window.mcp.requestCapabilityOS(id);if(!osr.ok&&osr.status!=='managed'){showInfo(tr('permissionRequired'),`${title} cannot be set to Allow until the required operating system permission is granted.`);await renderConfig();return}}await window.mcp.setCapabilityPermission(id,p);await renderConfig()}));cl.appendChild(row)});Object.entries(c.tools||{}).forEach(([name,permission])=>{const row=document.createElement('div');row.className='permission-row';const code=document.createElement('code');code.textContent=name;row.append(code,permControl(name,permission,p=>window.mcp.setToolPermission(name,p)));pl.appendChild(row)});(c.servers||[]).forEach(s=>{const card=document.createElement('div');card.className='mcp-server';const head=document.createElement('div');head.className='mcp-server-head';const info=document.createElement('div'),h=document.createElement('h3'),sm=document.createElement('small');h.textContent=s.name||'MCP Server';sm.textContent=s.transport==='streamable-http'?(s.url||'Remote MCP'):(s.command||'Local MCP');info.append(h,sm);const discovered=(c.discovery||{})[s.id]||[];const status=document.createElement('div');const serverConnected=s.managed_integration==='github-official'?!!githubStatus?.connected:discovered.length>0;status.className='mcp-status '+(serverConnected?'connected':'pending');status.textContent=serverConnected?`Connected · ${discovered.length} tools`:(s.managed_integration==='github-official'&&githubStatus?.configured?'Authentication required':'Not connected');info.appendChild(status);const lab=document.createElement('label');lab.className='switch';const chk=document.createElement('input');chk.type='checkbox';chk.checked=s.enabled!==false;const slider=document.createElement('span');slider.className='slider';chk.onchange=async()=>{await window.mcp.setServerEnabled(s.id,chk.checked);await window.mcp.action('restart');setTimeout(refresh,400)};lab.append(chk,slider);const controls=document.createElement('div');controls.className='server-controls';const remove=document.createElement('button');remove.className='remove-server';remove.textContent='Remove';remove.onclick=()=>showConfirm(`Remove ${s.name}?`,async()=>{await window.mcp.removeServer(s.id);await window.mcp.action('restart');await renderConfig()});const connect=document.createElement('button');connect.className='remove-server';connect.textContent=serverConnected?'Reconnect':'Connect';connect.onclick=async()=>{connect.disabled=true;connect.textContent='Connecting…';let r;if(s.managed_integration==='github-official'){const draft=await githubConnectDialog(githubStatus||{});if(!draft){connect.disabled=false;connect.textContent=serverConnected?'Reconnect':'Connect';return}r=await window.mcp.connectGitHubTool(draft)}else r=await window.mcp.connectServer(s.id);if(!r.ok)showInfo(r.title||'MCP connection failed',r.error||'Could not connect to this MCP server.');else if(s.managed_integration==='github-official')showInfo('GitHub connected',r.message||'GitHub authentication completed.');await renderConfig()};controls.append(connect,remove,lab);head.append(info,controls);card.appendChild(head);const stored=s.tools||{},tools=discovered.map(n=>[n,stored[n]||'confirm']);if(tools.length){tools.forEach(([name,p])=>{const row=document.createElement('div');row.className='permission-row';const code=document.createElement('code');code.textContent=name;row.append(code,permControl(name,p,x=>window.mcp.setServerToolPermission(s.id,name,x)));card.appendChild(row)})}else{const note=document.createElement('div');note.className='server-note';note.textContent='Tool permissions will appear after this server is discovered by the agent.';card.appendChild(note)}ml.appendChild(card)})}
$('#reloadMcp').onclick=renderConfig;
function githubConnectDialog(status={}){return new Promise(resolve=>{const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<div class="modal github-connect-modal"><h2>${status?.configured?'Reconnect GitHub':'Connect GitHub'}</h2><p class="modal-help">Use a fine-grained Personal Access Token. The token is stored only in this device's credential vault and is never written to MCP configuration files.</p><div class="github-token-help"><b>Recommended token setup</b><ol><li>Choose only the repositories MCPtoAI should access.</li><li>Give only the read permissions you need, such as Contents: Read, Issues: Read and Pull requests: Read.</li><li>Set an expiration date.</li></ol><button data-create-token type="button">Create fine-grained token ↗</button></div><label>Personal Access Token<input data-token type="password" autocomplete="off" placeholder="github_pat_…"></label><label class="github-readonly"><input data-readonly type="checkbox" checked><span><b>Read-only mode</b><small>Recommended. GitHub MCP will not expose tools that modify repositories, issues or pull requests.</small></span></label><p class="modal-error" data-error></p><div class="modal-actions"><button data-cancel>Cancel</button><button data-connect class="accent">Connect</button></div></div>`;const done=v=>{back.remove();resolve(v)};back.querySelector('[data-cancel]').onclick=()=>done(null);back.querySelector('[data-create-token]').onclick=()=>window.mcp.openGitHubTokenPage();back.querySelector('[data-connect]').onclick=()=>{const token=back.querySelector('[data-token]').value.trim();if(!token||token.length<20){back.querySelector('[data-error]').textContent='Paste a valid GitHub Personal Access Token.';return}done({token,read_only:back.querySelector('[data-readonly]').checked})};back.onmousedown=e=>{if(e.target===back)done(null)};document.body.appendChild(back);setTimeout(()=>back.querySelector('[data-token]').focus(),0)})}
$('#connectGithub').onclick=async()=>{const b=$('#connectGithub'),st=await window.mcp.githubToolStatus(),draft=await githubConnectDialog(st||{});if(!draft)return;const old=b.textContent;b.disabled=true;b.textContent='Connecting…';try{const r=await window.mcp.connectGitHubTool(draft);if(!r?.ok)showInfo('GitHub connection failed',r?.error||'Could not connect the official GitHub MCP server.');else showInfo('GitHub connected',r.message||'GitHub authentication completed.');await renderConfig()}finally{b.disabled=false;b.textContent=old;await renderConfig()}};
$('#customMcpCard').onclick=()=>{modal.classList.remove('hidden');$('#mcpName').focus()};
function googleDriveConnectDialog(status={}){return new Promise(resolve=>{const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<div class="modal gdrive-modal"><h2>Connect Google Drive</h2><p class="modal-help">MCPtoAI uses only the non-restricted <code>drive.file</code> permission. It can access only files you explicitly choose with Google Picker.</p><div class="gdrive-choice"><button data-mode="managed" class="gdrive-choice-card accent"><b>Connect with Google</b><small>Recommended · Sign in, choose files, allow access.</small></button><button data-mode="byo" class="gdrive-choice-card"><b>Use your own OAuth app</b><small>Advanced · Use your own Google Cloud Client ID and Secret.</small></button></div><div data-byo class="hidden gdrive-byo"><h3>Advanced setup</h3><ol><li>Open Google Cloud Console and create or select a project.</li><li>APIs & Services → Library: enable <b>Google Drive API</b> and <b>Google Picker API</b>.</li><li>Google Auth Platform → Branding/Audience: configure the consent screen. If the app is in Testing, add your Google account as a test user.</li><li>Google Auth Platform → Data Access: add only <code>https://www.googleapis.com/auth/drive.file</code>.</li><li>Clients → Create Client → <b>Desktop app</b>.</li><li>No redirect URI needs to be added manually; MCPtoAI uses a temporary <code>127.0.0.1</code> loopback callback.</li><li>Paste the Desktop Client ID and Client Secret below.</li></ol><label>Desktop OAuth Client ID<input data-client-id autocomplete="off" placeholder="...apps.googleusercontent.com"></label><label>Desktop OAuth Client Secret<input data-client-secret type="password" autocomplete="off" placeholder="GOCSPX-..."></label><p class="modal-error" data-error></p><div class="modal-actions"><button data-back>Back</button><button data-connect class="accent">Connect & Choose Files</button></div></div><div data-main-actions class="modal-actions"><button data-cancel>Cancel</button>${status?.connected?'<button data-disconnect>Disconnect</button>':''}</div></div>`;const done=v=>{back.remove();resolve(v)};back.querySelector('[data-cancel]')?.addEventListener('click',()=>done(null));back.querySelector('[data-disconnect]')?.addEventListener('click',()=>done({disconnect:true}));const byo=back.querySelector('[data-byo]'),main=back.querySelector('[data-main-actions]');back.querySelector('[data-mode="managed"]').onclick=()=>done({mode:'managed',append:!!status?.connected});back.querySelector('[data-mode="byo"]').onclick=()=>{byo.classList.remove('hidden');main.classList.add('hidden')};back.querySelector('[data-back]').onclick=()=>{byo.classList.add('hidden');main.classList.remove('hidden')};back.querySelector('[data-connect]').onclick=()=>{const client_id=back.querySelector('[data-client-id]').value.trim(),client_secret=back.querySelector('[data-client-secret]').value;if(!client_id||!client_secret){back.querySelector('[data-error]').textContent='Client ID and Client Secret are required.';return}done({mode:'byo',client_id,client_secret,append:!!status?.connected})};back.onmousedown=e=>{if(e.target===back)done(null)};document.body.appendChild(back)})}
$('#connectGoogleDrive').onclick=async()=>{const b=$('#connectGoogleDrive');const st=await window.mcp.googleDriveToolStatus();const draft=await googleDriveConnectDialog(st||{});if(!draft)return;if(draft.disconnect){const r=await window.mcp.disconnectGoogleDriveTool();if(!r.ok)showInfo('Google Drive disconnect failed',r.error||'Could not disconnect Google Drive.');await renderConfig();return}b.disabled=true;b.textContent='Connecting…';try{const r=await window.mcp.connectGoogleDriveTool(draft);if(!r.ok)showInfo('Google Drive connection failed',r.error||'Could not connect Google Drive.');else showInfo('Google Drive connected',`${r.selected||0} file${r.selected===1?'':'s'} selected. You can add more files at any time.`);await renderConfig()}finally{b.disabled=false}};
