const modal=$('#modal'),transport=$('#mcpTransport');const addMcpBtn=$('#addMcpBtn');if(addMcpBtn)addMcpBtn.onclick=()=>{modal.classList.remove('hidden');$('#mcpName').focus()};$('#cancelMcp').onclick=()=>modal.classList.add('hidden');transport.onchange=()=>{$('#urlField').classList.toggle('hidden',transport.value==='stdio');$('#commandField').classList.toggle('hidden',transport.value!=='stdio');$('#argsField').classList.toggle('hidden',transport.value!=='stdio')};$('#saveMcp').onclick=async()=>{let args=[],env={},headers={};try{args=$('#mcpArgs').value.trim()?JSON.parse($('#mcpArgs').value):[];env=$('#mcpEnv').value.trim()?JSON.parse($('#mcpEnv').value):{};headers=$('#mcpHeaders').value.trim()?JSON.parse($('#mcpHeaders').value):{}}catch{$('#modalError').textContent='Args, environment and headers must be valid JSON.';return}if(!Array.isArray(args)||typeof env!=='object'||Array.isArray(env)||typeof headers!=='object'||Array.isArray(headers)){$('#modalError').textContent='Args must be an array; env and headers must be objects.';return}const draft={name:$('#mcpName').value,transport:transport.value,url:$('#mcpUrl').value,command:$('#mcpCommand').value,args,env,headers},r=await window.mcp.addServer(draft);if(!r.ok){$('#modalError').textContent=r.error||'Could not add server';return}modal.classList.add('hidden');$('#modalError').textContent='';$('#mcpName').value='';$('#mcpUrl').value='';$('#mcpCommand').value='';await window.mcp.action('restart');await renderConfig();const cr=await window.mcp.connectServer(r.id);if(!cr.ok)showInfo(cr.title||'MCP added, connection pending',cr.error||'Use Connect to try again.');await renderConfig()};

function showConfirm(message,onConfirm){const back=document.createElement('div');back.className='modal-backdrop';const box=document.createElement('div');box.className='modal';const h=document.createElement('h2');h.textContent='Confirm action';const p=document.createElement('p');p.textContent=message;p.style.color='#8793a5';const actions=document.createElement('div');actions.className='modal-actions';const cancel=document.createElement('button');cancel.textContent='Cancel';const ok=document.createElement('button');ok.textContent='Remove';ok.className='accent';cancel.onclick=()=>back.remove();ok.onclick=async()=>{ok.disabled=true;await onConfirm();back.remove()};actions.append(cancel,ok);box.append(h,p,actions);back.appendChild(box);back.onmousedown=e=>{if(e.target===back)back.remove()};document.body.appendChild(back)}

async function renderProviders(){const [d,detected]=await Promise.all([window.mcp.providerStatus(),window.mcp.detectLocal()]);const localState=Object.fromEntries(detected.map(x=>[x.id,x])),select=$('#providerSelect');providerMeta=Object.fromEntries(d.providers.map(p=>[p.id,p]));select.innerHTML='';d.providers.filter(p=>p.chat!==false).forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name;select.appendChild(o)});select.value=d.provider;$('#providerModel').value=d.model||'';$('#providerBaseUrl').value=d.openai_base_url||'';const wrap=$('#providerCards');wrap.innerHTML='';const names=Object.fromEntries(d.providers.map(p=>[p.id,p.name]));d.providers.forEach(p=>{const card=document.createElement('div');card.className='provider-card'+(p.local?' local':'');const h=document.createElement('h3');h.textContent=names[p.id];const state=document.createElement('div');state.className='key-state'+((p.has_key||p.local)?' ok':'');state.textContent=p.local?((localState[p.id]?.running?`Detected · ${localState[p.id].models.length} models`:'Not detected')+' · no API key required'):(p.has_key?'API key configured':'API key not configured');if(p.chat===false){const tag=document.createElement('small');tag.textContent=p.credential_name?`${p.credential_name} · media provider`:'Media provider';card.append(h,state,tag);if(p.id==='replicate'){const lab=document.createElement('label');lab.className='provider-media-model';const cap=document.createElement('small');cap.textContent='Image model';const row=document.createElement('div');row.className='provider-key';const mi=document.createElement('input');mi.type='text';mi.value=d.replicate_image_model||'black-forest-labs/flux-1.1-pro';mi.placeholder='black-forest-labs/flux-1.1-pro';mi.autocomplete='off';const save=document.createElement('button');save.textContent='Save model';save.onclick=async()=>{const r=await window.mcp.saveReplicateModel(mi.value);if(!r.ok)showInfo('Invalid Replicate model',r.error||'Enter owner/model');else{mi.value=r.model;showInfo('Replicate model saved',r.model)}};row.append(mi,save);lab.append(cap,row);card.appendChild(lab)}}else card.append(h,state);if(!p.local){const row=document.createElement('div');row.className='provider-key';const input=document.createElement('input');input.type='password';input.placeholder=p.has_key?'Enter new key to replace':'Enter API key';input.autocomplete='off';const set=document.createElement('button');set.textContent=p.has_key?'Replace':'Set';set.onclick=async()=>{if(!input.value.trim())return;const r=await window.mcp.setProviderKey(p.id,input.value);input.value='';if(r.ok)await renderProviders()};row.append(input,set);card.appendChild(row);if(p.has_key){const remove=document.createElement('button');remove.className='remove-key';remove.textContent='Remove key';remove.onclick=()=>showConfirm(`Remove ${names[p.id]} API key from this device?`,async()=>{await window.mcp.removeProviderKey(p.id);await renderProviders()});card.appendChild(remove)}if(p.custom){const del=document.createElement('button');del.className='remove-key';del.textContent='Remove provider';del.onclick=()=>showConfirm(`Remove custom provider ${names[p.id]}?`,async()=>{await window.mcp.removeCustomProvider(p.id);await renderProviders()});card.appendChild(del)}}else{const hint=document.createElement('small');hint.textContent=p.id==='ollama'?'Default: http://127.0.0.1:11434/v1':p.id==='lmstudio'?'Default: http://127.0.0.1:1234/v1':'Enter your OpenAI-compatible local endpoint above.';card.appendChild(hint)}wrap.appendChild(card)})}
const localDefaults={ollama:'http://127.0.0.1:11434/v1',lmstudio:'http://127.0.0.1:1234/v1'};function providerDefaults(force=false){const p=$('#providerSelect').value,u=$('#providerBaseUrl'),known=Object.values(localDefaults);if(localDefaults[p]&&(force||!u.value.trim()||known.includes(u.value.trim())))u.value=localDefaults[p];else if(!['ollama','lmstudio','local','openai'].includes(p)&&known.includes(u.value.trim()))u.value=''}
$('#providerSelect').addEventListener('change',()=>{const p=$('#providerSelect').value,m=providerMeta[p];if(m?.base_url)$('#providerBaseUrl').value=m.base_url;else providerDefaults(true)});
$('#detectModels').onclick=async()=>{providerDefaults();const b=$('#detectModels'),box=$('#modelResults');b.disabled=true;b.textContent='Detecting…';box.classList.add('hidden');const r=await window.mcp.listModels({provider:$('#providerSelect').value,model:$('#providerModel').value,openai_base_url:$('#providerBaseUrl').value});b.disabled=false;b.textContent='Detect models';if(!r.ok){showInfo('Provider not reachable',r.error||'Could not discover models. Make sure the local model server is running.');return}box.innerHTML='';(r.models||[]).forEach(m=>{const x=document.createElement('button');x.textContent=m.id;x.onclick=()=>{$('#providerModel').value=m.id};box.appendChild(x)});box.classList.toggle('hidden',!r.models?.length);if(!r.models?.length)showInfo('No models found','The provider responded, but did not advertise any models.')};
$('#saveProvider').onclick=async()=>{if(!$('#providerModel').value.trim()){showInfo('Model required','Choose a detected model or enter its model ID.');return}await window.mcp.saveProvider({provider:$('#providerSelect').value,model:$('#providerModel').value,openai_base_url:$('#providerBaseUrl').value});await window.mcp.action('restart');await renderProviders();setTimeout(refresh,500)};renderProviders();

function showInfo(title,message){const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<div class="modal"><h2></h2><p style="color:#8793a5"></p><div class="modal-actions"><button class="accent">OK</button></div></div>`;back.querySelector('h2').textContent=title;back.querySelector('p').textContent=message;back.querySelector('button').onclick=()=>back.remove();document.body.appendChild(back)}
const legalCopy={
privacy:`<h3>Privacy Policy</h3><p>MCPtoAI is provided by BKTY LTD, Company No. 12845913, registered at 29 Watts Lane, Rugby, England, CV21 4PE.</p><h3>Data used to provide the service</h3><p>MCPtoAI uses account authentication and registers devices so that your web session can communicate with devices you have connected. The relay service processes the information needed to route authenticated requests and responses between your account and your connected device.</p><h3>Data kept on your device</h3><p>AI provider API keys, OAuth refresh tokens and device credentials are stored using the operating system credential store where supported. MCP server configuration, permissions and application settings are stored locally on your device. MCPtoAI does not intentionally send your provider API keys to BKTY LTD servers.</p><p>For the managed Google Drive connection, Google OAuth authorization-code exchanges and refreshes pass through MCPtoAI servers so the application client secret is not distributed to desktop clients. These Google access and refresh tokens are relayed back to your device and are not stored by MCPtoAI servers.</p><h3>AI providers and MCP servers</h3><p>When you choose an AI provider or connect an MCP server, prompts, tool inputs, tool outputs or other content required for that operation may be sent directly to that provider or MCP service. Those third parties process data under their own terms and privacy policies.</p><h3>Device tools</h3><p>Tools you enable can access files, processes, applications, URLs or commands within the permissions you configure. Use Off, Ask and Allow controls to limit access. You are responsible for choosing which tools and MCP servers to trust.</p><h3>Retention and deletion</h3><p>Local settings and logs remain on the device until removed. Account and device records required by the MCPtoAI service may remain until they are deleted in accordance with the service's account and retention procedures.</p><h3>Contact</h3><p>For privacy or product questions, contact BKTY LTD through the company website.</p>`,
terms:`<h3>Terms of Use</h3><p>By using MCPtoAI you instruct software running on your device to connect AI providers and MCP servers to tools you choose to expose. You must only connect systems, accounts and data that you are authorised to use.</p><h3>Your responsibility</h3><p>You control tool permissions and connected MCP servers. Commands and tool actions can modify files, applications, remote services or other resources. Review Ask prompts and use least-privilege permissions where appropriate.</p><h3>Third-party services</h3><p>AI providers, authentication providers and MCP servers are separate services. Their availability, pricing, content and data practices are governed by their own terms.</p><h3>Service availability</h3><p>MCPtoAI may change as the product develops. No software or network service can be guaranteed to be uninterrupted or error-free. Keep appropriate backups before allowing tools to modify important data.</p><h3>Company</h3><p>MCPtoAI is provided by BKTY LTD, Company No. 12845913, registered at 29 Watts Lane, Rugby, England, CV21 4PE.</p>`,
licenses:`<h3>Open Source & Licences</h3><p>MCPtoAI Desktop and its bundled agent include open-source software. Third-party components remain subject to their respective licence terms and copyright notices.</p><p>The application includes technologies and libraries from the Electron, Python, MCP and related open-source ecosystems. A complete machine-readable third-party notices file will be included in release packages before public distribution.</p>`,
about:`<h3>About MCPtoAI</h3><p>MCPtoAI connects your authenticated web experience to an agent running on your own computer. Provider credentials stay on the device and the local agent controls access to device and MCP tools according to the permissions you select.</p><p>Publisher: BKTY LTD · Company No. 12845913<br>Registered address: 29 Watts Lane, Rugby, England, CV21 4PE<br>Copyright © 2026 BKTY LTD.</p>`};
async function showLegal(k){$('#legalContent').innerHTML=legalCopy[k];if(k==='about'){const i=await window.mcp.info(),v=$('#aboutVersion'),p=$('#aboutPlatform');if(v)v.textContent=i.version;if(p)p.textContent=`${i.platform} ${i.arch}`;}document.querySelectorAll('.legal-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.legal===k))}document.querySelectorAll('.legal-tabs button').forEach(b=>b.onclick=()=>showLegal(b.dataset.legal));showLegal('privacy');

async function permissionStep(){const step=$('#onboardStep'),st=await window.mcp.permissionStatus();if(st.platform!=='darwin'){await window.mcp.markPermissionsSeen();return onboardingState()}step.innerHTML=`<h1>Device permissions</h1><p>MCPtoAI can work without broad macOS access. Enable extra permissions only for tools you want to use.</p><div class="permission-setup"><div><b>Accessibility</b><small>Needed only for tools that control other app interfaces.</small><button id="reqAccessibility">${st.accessibility?'Enabled':'Enable…'}</button></div><div><b>Full Disk Access</b><small>Optional. For protected locations: Show Agent, open Settings, press + and add MCPtoAI Device Agent.</small><span class="permission-buttons"><button id="showAgent">1. Show Agent</button><button id="openFullDisk">2. Open Settings…</button></span></div></div><div class="onboard-actions"><button id="permissionContinue" class="accent">Continue</button></div>`;$('#reqAccessibility').onclick=async()=>{await window.mcp.requestAccessibility();setTimeout(permissionStep,500)};$('#showAgent').onclick=()=>window.mcp.revealAgent();$('#openFullDisk').onclick=()=>window.mcp.openPermission('fullDisk');$('#permissionContinue').onclick=async()=>{await window.mcp.markPermissionsSeen();await onboardingState()}}
async function onboardingState(){const o=$('#onboarding'),step=$('#onboardStep');let st;try{st=await window.mcp.paired()}catch{st={installed:false,paired:false,permissions_seen:false}}if(st.installed&&!st.permissions_seen){o.classList.remove('hidden');return permissionStep()}if(st.installed&&st.paired){o.classList.add('hidden');await renderAccount();return}o.classList.remove('hidden');if(!st.installed){step.innerHTML=`<h1>${tr('setupDevice')}</h1><p>${tr('setupLead')}</p><div class="onboard-actions"><button id="onboardInstall" class="accent">${tr('setupButton')}</button></div>`;$('#onboardInstall').onclick=async()=>{step.innerHTML=`<h1>${tr('installing')}</h1><div class="onboard-status"><span class="spinner"></span>${tr('preparing')}</div>`;const r=await window.mcp.installAgent();if(!r.ok){step.innerHTML='<h1>Setup could not finish</h1><p></p><div class="onboard-actions"><button id="retryInstall" class="accent">Try again</button></div>';step.querySelector('p').textContent=r.error||'Unknown installation error';$('#retryInstall').onclick=onboardingState;return}await onboardingState()};return}step.innerHTML=`<h1>${tr('connectAccount')}</h1><p>${tr('connectLead')}</p><div class="onboard-actions"><button id="onboardLogin" class="accent">${tr('signIn')}</button></div>`;$('#onboardLogin').onclick=async()=>{step.innerHTML=`<h1>${tr('waitingSignIn')}</h1><div class="onboard-status"><span class="spinner"></span>${tr('completeSignIn')}</div>`;const r=await window.mcp.login();if(!r.ok){step.innerHTML='<h1>Pairing was not completed</h1><p></p><div class="onboard-actions"><button id="retryLogin" class="accent">Try again</button></div>';step.querySelector('p').textContent=r.error||'Please try again.';$('#retryLogin').onclick=onboardingState;return}await window.mcp.action('restart');await onboardingState();refresh()}}

async function autoUpgradeBundledAgent(){try{const s=await window.mcp.agentUpdateStatus();if(!s?.updateAvailable)return s;const r=await window.mcp.autoUpgradeAgent();if(!r?.ok){console.warn('Device Agent automatic upgrade failed:',r?.error||'unknown error');return s}return await window.mcp.agentUpdateStatus()}catch(e){console.warn('Device Agent automatic upgrade check failed:',e);return null}}
async function bootstrapDesktop(){await autoUpgradeBundledAgent();await onboardingState();await refreshAgentUpdate();await Promise.allSettled([loadLocalChatOptions(),loadCloudChats()])}
bootstrapDesktop();

async function refreshAgentUpdate(){const s=await window.mcp.agentUpdateStatus(),b=$('#updateAgent');const pending=!!s.updateAvailable;b.classList.toggle('hidden',!pending);if(pending)$('#updateStatus').textContent=`Device Agent ${s.installed} · bundled ${s.bundled} available`;return s}
$('#updateAgent').onclick=async()=>{const b=$('#updateAgent');b.disabled=true;b.textContent='Updating…';const r=await window.mcp.updateAgent();b.disabled=false;b.textContent='Update Device Agent';if(!r.ok){showInfo('Agent update failed',r.error||'The previous agent was restored.');return}showInfo('Device Agent updated',`Version ${r.version} installed and restarted.`);await refreshAgentUpdate();refresh()};
$('#checkUpdates').onclick=async()=>{const b=$('#checkUpdates'),st=$('#updateStatus');b.disabled=true;b.textContent='Checking…';const r=await window.mcp.checkUpdates();if(!r.ok){b.disabled=false;b.textContent='Check for Updates';st.textContent=r.error||'Update check failed.';await refreshAgentUpdate();return}const m=r.manifest||{},desktop=m.desktop||{},remoteAgent=m.agent||{},local=r.agent||{};if(r.desktopUpdateAvailable&&desktop.version){b.textContent='Downloading…';st.textContent=`MCPtoAI ${desktop.version} is available. Downloading update…`;const d=await window.mcp.downloadDesktopUpdate();if(!d.ok){b.disabled=false;b.textContent='Check for Updates';st.textContent=d.error||'Update download failed.';return}if(d.available&&d.downloaded){b.disabled=false;b.textContent='Restart & Install';b.onclick=async()=>{b.disabled=true;b.textContent='Restarting…';const x=await window.mcp.installDesktopUpdate();if(!x.ok){b.disabled=false;b.textContent='Restart & Install';st.textContent=x.error||'Update installation failed.'}};st.textContent=`MCPtoAI ${d.version} downloaded and verified. Restart to install.`;return}}b.disabled=false;b.textContent='Check for Updates';st.textContent=`Desktop ${r.current} is up to date · Device Agent ${local.installed||'not installed'}${remoteAgent.version?' · latest '+remoteAgent.version:''}`;await refreshAgentUpdate()};
refreshAgentUpdate();

