async function renderHistoryStorage(){const r=await window.mcp.historyStorage();currentHistoryProvider=r?.provider==='local'?'local':'mcptoai';const select=$('#historyStorageSelect');if(select)select.value=currentHistoryProvider;updateHistoryStorageCopy();return currentHistoryProvider}
async function renderAccount(){let st;try{st=await window.mcp.paired()}catch{st={installed:false,paired:false}}const connected=!!(st.installed&&st.paired);$('#accountState').textContent=connected?'Connected':'Not connected';$('#accountDetail').textContent=connected?'This Mac is connected to your MCPtoAI web account.':'Connect this Mac to use Web Chats and remote access.';$('#settingsAccountState').textContent=connected?'Connected — this device can use MCPtoAI Web.':'Not connected — connect this device to your MCPtoAI account.';$('#accountConnect').classList.toggle('hidden',connected);$('#settingsConnect').classList.toggle('hidden',connected);$('#accountWeb').classList.toggle('hidden',!connected);$('#settingsOpenWeb').classList.toggle('hidden',!connected)}
async function connectAccountFromApp(){const buttons=[$('#accountConnect'),$('#settingsConnect')];buttons.forEach(b=>{b.disabled=true;b.textContent='Waiting for sign in…'});const r=await window.mcp.login();buttons.forEach(b=>{b.disabled=false;b.textContent='Connect Account'});if(!r.ok){showInfo('Connection was not completed',r.error||'Please try again.');return}await window.mcp.action('restart');await renderAccount();await refresh()}
