const historyStorageSelect=$('#historyStorageSelect');if(historyStorageSelect){historyStorageSelect.onchange=async e=>{const previous=currentHistoryProvider,next=e.target.value;if(!['mcptoai','local'].includes(next)){e.target.value=previous;return}e.target.disabled=true;const r=await window.mcp.setHistoryStorage(next);e.target.disabled=false;if(!r?.ok){e.target.value=previous;showInfo('Could not change history storage',r?.error||'The setting was not saved.');return}currentHistoryProvider=next;activeChatId=null;localHistory=[];syncedContext=[];showArchivedChats=false;renderLocalHistory();updateHistoryStorageCopy();await loadCloudChats();showInfo('Conversation history storage',next==='local'?'New conversations and history are now stored only on this device. Existing MCPtoAI Cloud conversations were not moved or deleted.':'MCPtoAI Cloud history is active again. Local-only conversations remain on this device.')};}
