$('#testProvider').onclick=async()=>{providerDefaults();const b=$('#testProvider'),box=$('#providerProbe'),v={provider:$('#providerSelect').value,model:$('#providerModel').value,openai_base_url:$('#providerBaseUrl').value};if(!v.model){showInfo('Select a model','Detect models or enter a model name before testing tool calling.');return}b.disabled=true;b.textContent='Testing…';box.className='provider-probe hidden';const r=await window.mcp.probeProvider(v);b.disabled=false;b.textContent='Test connection';if(!r.ok){showInfo('Provider not reachable',r.error||'Connection test failed.');return}box.className='provider-probe '+(r.tool_calling?'ok':'warn');box.textContent=`Reachable · ${(r.models||[]).length} model${(r.models||[]).length===1?'':'s'} · ${r.latency_ms} ms · Tool calling: ${r.tool_calling?'Supported':'Not detected'}`};

