// Unified Chats: one cloud-backed session list; execution still happens through the local Device Agent.
let localHistory=[],localFiles=[],activeChatId=null,syncedContext=[];
function renderAssistantContent(container,text){const raw=String(text??''),parts=raw.split('```');for(let i=0;i<parts.length;i++){const part=parts[i];if(i%2===0){if(!part)continue;const span=document.createElement('span');span.className='chat-rich-text';span.textContent=part;container.appendChild(span);continue}const nl=part.indexOf('\n'),langName=(nl>=0?part.slice(0,nl):'code').trim()||'code',code=nl>=0?part.slice(nl+1):part;const block=document.createElement('div');block.className='code-block';const head=document.createElement('div');head.className='code-head';const lang=document.createElement('span');lang.textContent=langName;const copy=document.createElement('button');copy.type='button';copy.textContent='Copy';copy.onclick=async()=>{try{await navigator.clipboard.writeText(code);copy.textContent='Copied ✓';setTimeout(()=>{if(copy.isConnected)copy.textContent='Copy'},1400)}catch{copy.textContent='Copy failed';setTimeout(()=>{if(copy.isConnected)copy.textContent='Copy'},1400)}};head.append(lang,copy);const pre=document.createElement('pre'),codeEl=document.createElement('code');codeEl.textContent=code;pre.appendChild(codeEl);block.append(head,pre);container.appendChild(block)}}
function chatBubble(role,text,meta='',images=[]){const d=document.createElement('div');d.className='chat-bubble '+role;const c=document.createElement('div');c.className='chat-bubble-content';if(role==='assistant')renderAssistantContent(c,text);else c.textContent=text;d.appendChild(c);for(const url of (images||[]).slice(0,4)){if(typeof url!=='string'||!url.startsWith('data:image/'))continue;const img=document.createElement('img');img.className='generated-image';img.src=url;img.alt='Screen capture';img.onclick=()=>openImageLightbox(url);d.appendChild(img)}if(role==='assistant'){const urls=String(text||'').match(/https:\/\/replicate\.delivery\/[^\s)]+/g)||[];for(const url of urls.slice(0,4)){const img=document.createElement('img');img.className='generated-image';img.src=url;img.alt='Generated image';img.loading='lazy';img.referrerPolicy='no-referrer';img.onclick=()=>openImageLightbox(url);d.appendChild(img)}}if(meta){const m=document.createElement('small');m.textContent=meta;d.appendChild(m)}return d}
function openImageLightbox(url){const lb=$('#imageLightbox'),img=$('#imageLightboxImg');img.src=url;lb.classList.remove('hidden')}
function closeImageLightbox(){$('#imageLightbox').classList.add('hidden');$('#imageLightboxImg').src=''}
$('#imageLightboxClose').onclick=closeImageLightbox;$('#imageLightbox').onclick=e=>{if(e.target.id==='imageLightbox')closeImageLightbox()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeImageLightbox()});
let localMentionItems=[];
async function updateLocalMentions(){const input=$('#localChatInput'),menu=$('#localMentionMenu'),m=input.value.match(/@([^\s]*)$/);if(!m){menu.classList.add('hidden');return}const q=m[1].toLowerCase(),items=[];const ps=await window.mcp.providerStatus().catch(()=>({}));const rep=(ps.providers||[]).find(x=>x.id==='replicate');if(rep?.has_key)items.push({name:'Replicate',sub:'Image · '+(ps.replicate_image_model||'black-forest-labs/flux-1.1-pro')});for(const o of [...$('#localMcp').options])if(o.value)items.push({name:o.textContent.replace(/\s*\([^)]*\)\s*$/,'').trim(),sub:'MCP',id:o.value});localMentionItems=items.filter(x=>!q||x.name.toLowerCase().includes(q));menu.innerHTML='';for(const x of localMentionItems){const b=document.createElement('button');b.type='button';b.innerHTML=`<span>${x.name==='Replicate'?'✦':'⌘'}</span><span><b>@${x.name}</b><small>${x.sub}</small></span>`;b.onmousedown=e=>{e.preventDefault();input.value=input.value.replace(/@[^\s]*$/,`@${x.name} `);menu.classList.add('hidden');input.focus()};menu.appendChild(b)}menu.classList.toggle('hidden',!localMentionItems.length)}
function renderLocalHistory(scrollToBottom=true){const box=$('#localMessages');const previous=box.scrollTop;box.innerHTML='';if(!localHistory.length){box.innerHTML=`<div class="chat-empty">${historyIsLocal()?'Start a conversation. History stays on this device.':'Start a conversation. It will be available on Web and this device.'}</div>`;return}for(const m of localHistory)box.appendChild(chatBubble(m.role,m.content,m.meta||'',m.images||[]));requestAnimationFrame(()=>{box.scrollTop=scrollToBottom?box.scrollHeight:previous;updateLocalScrollBottom()})}

function updateLocalScrollBottom(){const box=$('#localMessages'),btn=$('#localScrollBottom');if(!box||!btn)return;const away=box.scrollHeight-box.scrollTop-box.clientHeight>120;btn.classList.toggle('hidden',!away)}
const localMessagesEl=$('#localMessages');localMessagesEl?.addEventListener('scroll',updateLocalScrollBottom,{passive:true});$('#localScrollBottom')?.addEventListener('click',()=>{localMessagesEl?.scrollTo({top:localMessagesEl.scrollHeight,behavior:'smooth'})});
function renderLocalAttachments(){const w=$('#localAttachments');w.innerHTML='';w.classList.toggle('hidden',!localFiles.length);localFiles.forEach((f,i)=>{const chip=document.createElement('div');chip.className='attachment-chip';chip.textContent=(f.kind==='image'?'▧ ':'▤ ')+f.name;const x=document.createElement('button');x.textContent='×';x.onclick=()=>{localFiles.splice(i,1);renderLocalAttachments()};chip.appendChild(x);w.appendChild(chip)})}
async function loadLocalChatModels(provider,preferred=''){const ms=$('#localModel');ms.innerHTML='<option value="">Loading…</option>';ms.disabled=true;const r=await window.mcp.listModels({provider,model:preferred||'model'});ms.innerHTML='';if(r.ok&&Array.isArray(r.models)){for(const m of r.models){const id=typeof m==='string'?m:m.id;if(!id)continue;const o=document.createElement('option');o.value=id;o.textContent=id;ms.appendChild(o)}}if(!ms.options.length){const o=document.createElement('option');o.value=preferred||'';o.textContent=preferred||'No models available';ms.appendChild(o)}if(preferred&&[...ms.options].some(o=>o.value===preferred))ms.value=preferred;ms.disabled=false}
async function loadLocalChatOptions(){const [p,c]=await Promise.all([window.mcp.providerStatus(),window.mcp.config()]);const ps=$('#localProvider');ps.innerHTML='';for(const x of p.providers||[]){if(x.chat===false||(!x.local&&x.key!==false&&!x.has_key))continue;const o=document.createElement('option');o.value=x.id;o.textContent=x.name;ps.appendChild(o)}ps.value=[...ps.options].some(o=>o.value===p.provider)?p.provider:(ps.options[0]?.value||'');await loadLocalChatModels(ps.value,ps.value===p.provider?p.model:'');const mc=$('#localMcp');mc.innerHTML='<option value="">Auto / All enabled</option>';for(const srv of c.servers||[]){if(srv.enabled===false)continue;const o=document.createElement('option');o.value=srv.id;o.textContent=srv.name||'MCP Server';mc.appendChild(o)}}
$('#localProvider').onchange=async e=>{await loadLocalChatModels(e.target.value,'')};
async function newUnifiedChat(){activeChatId=null;localHistory=[];localFiles=[];syncedContext=[];renderLocalHistory();renderLocalAttachments();document.querySelectorAll('.cloud-chat-item').forEach(x=>x.classList.remove('active'));$('#localChatInput').focus()}
$('#clearLocalChat').onclick=newUnifiedChat;
$('#localAttach').onclick=async()=>{const r=await window.mcp.pickLocalFiles();if(r.ok&&r.files?.length){localFiles.push(...r.files);localFiles=localFiles.slice(0,8);renderLocalAttachments()}};
async function ensureCloudChat(provider,model){if(activeChatId)return activeChatId;const r=await window.mcp.createChat({provider,model});if(!r.ok||!r.data?.id)throw new Error(r.error||'Could not create chat');activeChatId=r.data.id;return activeChatId}
$('#localChatForm').onsubmit=async e=>{e.preventDefault();const input=$('#localChatInput');let text=input.value.trim();if(!text&&!localFiles.length)return;const textFiles=localFiles.filter(f=>f.kind==='text');if(textFiles.length)text+=(text?'\n\n':'')+textFiles.map(f=>`--- ${f.name} ---\n${f.text}`).join('\n\n');const images=localFiles.filter(f=>f.kind==='image').map(f=>({data_url:f.data_url}));const rawInput=input.value.trim();const capMatch=rawInput.match(/^@replicate(?:\s+|$)/i);const capability=capMatch?'replicate':'';if(capability)text=rawInput.replace(/^@replicate\s*/i,'').trim();const display=rawInput||`Attached ${localFiles.length} file(s)`;const context=syncedContext.slice(-40);const provider=$('#localProvider').value,model=$('#localModel').value,mcp=$('#localMcp').value;const send=$('#localChatSend');send.disabled=false;send.textContent='■';send.dataset.running='1';try{const sid=await ensureCloudChat(provider,model);const saved=await window.mcp.addChatMessage({session_id:sid,role:'user',content:text,model,tool_data:localFiles.length?{attachments:localFiles.map(f=>({name:f.name,kind:f.kind}))}:null});if(!saved.ok)throw new Error(saved.error||'Could not save message');localHistory.push({role:'user',content:display,meta:localFiles.length?localFiles.map(f=>f.name).join(' · '):''});syncedContext.push({role:'user',content:text});input.value='';localFiles=[];renderLocalAttachments();renderLocalHistory();const pending=chatBubble('assistant','Working on this device…');$('#localMessages').appendChild(pending);const r=await window.mcp.localChat({text,session_id:sid,language:window.I18N?.lang||'en',provider,model,images,preferred_mcp_server_ids:mcp?[mcp]:[],capability,context});pending.remove();if(!r.ok)throw new Error(r.error||'Chat failed');const answer=r.text||'(No response)';for(const ev of (r.events||[]).filter(x=>x?.type==='image'&&x.source==='capture_screen'&&typeof x.data_url==='string'&&x.data_url.startsWith('data:image/jpeg;base64,'))){localHistory.push({role:'assistant',content:`Screen capture · ${ev.width||'?'}×${ev.height||'?'}`,meta:'This device',images:[ev.data_url]})}for(const ev of (r.events||[]).filter(x=>x&&['tool_request','tool_result'].includes(x.type))){const er=await window.mcp.addChatMessage({session_id:sid,role:'tool',content:ev.preview||'',model,tool_name:ev.name||'',tool_data:ev});if(!er.ok)console.warn('Could not sync tool event:',er.error||'unknown');else syncedContext.push({role:'tool',content:ev.preview||'',tool_name:ev.name||'',tool_data:ev})}const savedAnswer=await window.mcp.addChatMessage({session_id:sid,role:'assistant',content:answer,model});if(!savedAnswer.ok)throw new Error(savedAnswer.error||'Could not save response');localHistory.push({role:'assistant',content:answer,meta:`This device · ${provider} · ${model}${mcp?' · MCP selected':''}`});syncedContext.push({role:'assistant',content:answer});renderLocalHistory();await loadCloudChats()}catch(err){localHistory.push({role:'assistant',content:'Error: '+err.message,meta:'This device'});renderLocalHistory()}finally{send.disabled=false;send.textContent='↑';delete send.dataset.running;input.focus()}};
$('#localChatSend').onclick=async e=>{const b=$('#localChatSend');if(b.dataset.running==='1'){e.preventDefault();e.stopPropagation();b.disabled=true;b.textContent='…';await window.mcp.cancelLocalChat({session_id:activeChatId||'new'})}};
$('#localChatInput').oninput=()=>updateLocalMentions();$('#localChatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){const menu=$('#localMentionMenu');if(!menu.classList.contains('hidden')&&localMentionItems.length){e.preventDefault();menu.querySelector('button')?.dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));return}e.preventDefault();$('#localChatForm').requestSubmit()}};

function askChatName(current){return new Promise(resolve=>{const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML='<div class="modal chat-rename-modal"><h2>Rename chat</h2><label>Chat name<input maxlength="160"></label><div class="modal-actions"><button data-cancel>Cancel</button><button class="accent" data-save>Save</button></div></div>';const input=back.querySelector('input');input.value=current;const done=v=>{back.remove();resolve(v)};back.querySelector('[data-cancel]').onclick=()=>done(null);back.querySelector('[data-save]').onclick=()=>done(input.value.trim());input.onkeydown=e=>{if(e.key==='Enter')done(input.value.trim());if(e.key==='Escape')done(null)};document.body.appendChild(back);setTimeout(()=>{input.focus();input.select()},0)})}
// Arşiv görünümü durumu. İlk sürümden beri tanımsızdı; loadCloudChats her çağrıda
// ReferenceError verdiği için Desktop'taki sohbet listesi "Loading…" olarak kalıyordu.
let showArchivedChats=false;
async function loadCloudChats(){const list=$('#cloudChatList');list.innerHTML='<div class="chat-muted">Loading…</div>';const r=await window.mcp.cloudChats({archived:showArchivedChats});if(!r.ok||!Array.isArray(r.data)){list.innerHTML=`<div class="chat-muted">${historyIsLocal()?'Could not load local conversation history.':'Could not load chats. Make sure this device is paired.'}</div>`;return}list.innerHTML='';if(!r.data.length){list.innerHTML=`<div class="chat-muted">${showArchivedChats?'No archived chats.':'No chats yet.'}</div>`;return}for(const c of r.data){const row=document.createElement('div');row.className='cloud-chat-row';const b=document.createElement('button');b.className='cloud-chat-item'+(c.id===activeChatId?' active':'');const title=document.createElement('b');title.textContent=(c.is_pinned?'⌖  ':'')+(c.title||'New chat');const meta=document.createElement('small');meta.textContent=`${c.message_count||0} messages${c.model?' · '+c.model:''}`;b.append(title,meta);b.onclick=()=>openCloudChat(c,b);const more=document.createElement('button');more.className='cloud-chat-more';more.textContent='⋯';more.title='Chat options';const menu=document.createElement('div');menu.className='cloud-chat-menu hidden';const action=(label,cls,fn)=>{const x=document.createElement('button');x.textContent=label;if(cls)x.className=cls;x.onclick=async ev=>{ev.stopPropagation();menu.classList.add('hidden');await fn()};menu.appendChild(x)};action('✎  Rename','',async()=>{const name=await askChatName(c.title||'New chat');if(name===null||!name.trim())return;const u=await window.mcp.updateChat({session_id:c.id,title:name.trim()});if(!u.ok)return showInfo('Could not rename chat',u.error||'Update failed.');await loadCloudChats()});action(c.is_pinned?'⌖  Unpin':'⌖  Pin','',async()=>{const u=await window.mcp.updateChat({session_id:c.id,is_pinned:!c.is_pinned});if(!u.ok)return showInfo('Could not update chat',u.error||'Update failed.');await loadCloudChats()});action('⇩  Export as text','',async()=>exportCloudChat(c,'txt'));action('{ }  Export as JSON','',async()=>exportCloudChat(c,'json'));action(showArchivedChats?'□  Unarchive':'□  Archive','',async()=>{const u=await window.mcp.updateChat({session_id:c.id,is_archived:!showArchivedChats});if(!u.ok)return showInfo('Could not archive chat',u.error||'Update failed.');if(activeChatId===c.id){activeChatId=null;localHistory=[];syncedContext=[];renderLocalHistory()}await loadCloudChats()});action('⌫  Delete','danger',async()=>{if(!confirm(`Delete "${c.title||'New chat'}"? This permanently deletes the chat and its messages from ${historyIsLocal()?'this device':'MCPtoAI Cloud'}.`))return;const d=await window.mcp.deleteChat(c.id);if(!d.ok)return showInfo('Could not delete chat',d.error||'Delete failed.');if(activeChatId===c.id){activeChatId=null;localHistory=[];syncedContext=[];renderLocalHistory()}await loadCloudChats()});more.onclick=ev=>{ev.stopPropagation();document.querySelectorAll('.cloud-chat-menu').forEach(x=>x!==menu&&x.classList.add('hidden'));menu.classList.toggle('hidden')};row.append(b,more,menu);list.appendChild(row)}}
async function exportCloudChat(c,format){const r=await window.mcp.cloudChat(c.id);if(!r.ok||!r.data)return showInfo('Could not export chat','Could not load this conversation.');const e=await window.mcp.exportChat({format,title:c.title||'New chat',messages:r.data.messages||[]});if(!e.ok&&!e.canceled)showInfo('Could not export chat',e.error||'Export failed.')}
document.addEventListener('click',()=>document.querySelectorAll('.cloud-chat-menu').forEach(x=>x.classList.add('hidden')));
async function openCloudChat(c,button){document.querySelectorAll('.cloud-chat-item').forEach(x=>x.classList.remove('active'));button?.classList.add('active');const r=await window.mcp.cloudChat(c.id);if(!r.ok||!r.data){showInfo('Chat unavailable','Could not load this conversation.');return}activeChatId=c.id;syncedContext=(r.data.messages||[]).map(m=>({role:m.role,content:m.content||'',tool_name:m.tool_name||'',tool_data:m.tool_data??null}));localHistory=(r.data.messages||[]).filter(m=>m.role==='user'||m.role==='assistant').map(m=>({role:m.role,content:m.content||'',meta:m.model||''}));renderLocalHistory();if(c.provider&&[...$('#localProvider').options].some(o=>o.value===c.provider)){$('#localProvider').value=c.provider;await loadLocalChatModels(c.provider,c.model||'')}$('#localChatInput').focus()}
$('#refreshCloudChats').onclick=loadCloudChats;$('#archiveChatsSide').onclick=async()=>{showArchivedChats=!showArchivedChats;$('#archiveChatsSide').classList.toggle('active',showArchivedChats);$('#archiveChatsSide').title=showArchivedChats?'Back to chats':'Archived chats';await loadCloudChats()};
document.querySelector('[data-view="localchat"]').addEventListener('click',async()=>{await renderHistoryStorage();await Promise.allSettled([loadLocalChatOptions(),loadCloudChats()])});
window.mcp.onLocalApproval(req=>{const back=document.createElement('div');back.className='modal-backdrop';const box=document.createElement('div');box.className='modal';const h=document.createElement('h2');h.textContent='Allow tool action?';const p=document.createElement('p');p.style.color='#8793a5';p.textContent=`${req.tool} wants to run with:\n${JSON.stringify(req.arguments||{},null,2)}`;p.style.whiteSpace='pre-wrap';const actions=document.createElement('div');actions.className='modal-actions';const deny=document.createElement('button');deny.textContent='Deny';const allow=document.createElement('button');allow.textContent='Allow once';allow.className='accent';let answered=false;const answer=async ok=>{if(answered)return;answered=true;await window.mcp.approveLocal({approval_id:req.approval_id,approve:ok});back.remove()};deny.onclick=()=>answer(false);allow.onclick=()=>answer(true);back.onmousedown=e=>{if(e.target===back)answer(false)};actions.append(deny,allow);box.append(h,p,actions);back.appendChild(box);document.body.appendChild(back)});


function closeMobileNav(){document.body.classList.remove('mobile-nav-open')}
$('#mobileMenuButton')?.addEventListener('click',()=>document.body.classList.add('mobile-nav-open'));
$('#mobileMenuClose')?.addEventListener('click',closeMobileNav);$('#mobileNavBackdrop')?.addEventListener('click',closeMobileNav);
document.querySelectorAll('#appSidebar nav button').forEach(b=>b.addEventListener('click',()=>{if(innerWidth<=720)closeMobileNav()}));
addEventListener('resize',()=>{if(innerWidth>720)closeMobileNav();updateCloudBottom()});

// Responsive unified-chat chrome. Keep the conversation usable at narrow widths
// and let the user reclaim space from both the history pane and chat controls.
(function setupChatChrome(){
  const layout=document.querySelector('#localchat .chat-layout'), head=document.querySelector('#localchat .local-chat-head');
  const listToggle=$('#toggleChatList'), listShow=$('#showChatList'), controlsToggle=$('#toggleChatControls');
  if(!layout||!head||!listToggle||!listShow||!controlsToggle)return;
  const setListCollapsed=(collapsed,persist=true)=>{layout.classList.toggle('chat-list-collapsed',collapsed);listToggle.setAttribute('aria-expanded',String(!collapsed));listToggle.title=collapsed?'Show chats':'Collapse chats';listToggle.textContent=collapsed?'›':'‹';listShow.classList.toggle('hidden',!collapsed);if(persist)localStorage.setItem('mcptoai.chatListCollapsed',collapsed?'1':'0')};
  const setControlsCollapsed=(collapsed,persist=true)=>{head.classList.toggle('controls-collapsed',collapsed);controlsToggle.setAttribute('aria-expanded',String(!collapsed));controlsToggle.title=collapsed?'Expand chat controls':'Collapse chat controls';controlsToggle.textContent=collapsed?'⌄':'⌃';if(persist)localStorage.setItem('mcptoai.chatControlsCollapsed',collapsed?'1':'0')};
  listToggle.onclick=()=>setListCollapsed(!layout.classList.contains('chat-list-collapsed'));
  listShow.onclick=()=>setListCollapsed(false);
  controlsToggle.onclick=()=>setControlsCollapsed(!head.classList.contains('controls-collapsed'));
  $('#newChatSide')?.addEventListener('click',newUnifiedChat);
  const responsive=()=>{if(innerWidth<=600)setListCollapsed(true,false)};
  setListCollapsed(localStorage.getItem('mcptoai.chatListCollapsed')==='1',false);
  setControlsCollapsed(localStorage.getItem('mcptoai.chatControlsCollapsed')==='1',false);
  responsive(); addEventListener('resize',responsive);
})();

async function refreshWorkspace(){const w=await window.mcp.workspace();const el=$('#workspacePath');if(!el)return;el.textContent=w.configured?w.path:tr('workspaceDefaultLead')}
$('#chooseWorkspace').onclick=async()=>{const r=await window.mcp.chooseWorkspace();if(r?.ok){await refreshWorkspace();showInfo(tr('workspaceUpdated'),tr('workspaceUpdatedLead'))}};
refreshWorkspace();

// Terminal komutları: yalnızca bu cihazdan açılabilen yerel izin (web değiştiremez). Açıkken de
// her komut ve görev ayrıca onay ister.
async function renderTerminalState(el){let st={enabled:false};try{st=await window.mcp.shellAccess()}catch{}el.textContent=st.enabled?'✓ Enabled':'Enable';el.onclick=()=>{if(st.enabled){showConfirm('Turn off terminal commands? The AI will no longer be able to run commands or start background jobs on this computer. Jobs that are already running keep running.',async()=>{await window.mcp.setShellAccess(false);await renderConfig()})}else{showConfirm('Allow the AI to run terminal commands and long-running background jobs on this computer? Every command and every job still asks for your approval. This setting can only be changed on this computer.',async()=>{const r=await window.mcp.setShellAccess(true);if(!r||!r.ok)showInfo('Terminal commands',(r&&r.error)||'Could not enable terminal commands.');await renderConfig()})}}}
